import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.BVA38fkC.js";var i=JSON.parse(`{"title":"Goal-based net-interest planning","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/docs/strategies/goal-achievement.html"}],["meta",{"property":"og:title","content":"Goal-based net-interest planning | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/docs/strategies/goal-achievement.html"}],["meta",{"name":"twitter:title","content":"Goal-based net-interest planning | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"strategies/goal-achievement.md","filePath":"strategies/goal-achievement.md","lastUpdated":1793949598000}`),a={name:`strategies/goal-achievement.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="goal-based-net-interest-planning" tabindex="-1">Goal-based net-interest planning <a class="header-anchor" href="#goal-based-net-interest-planning" aria-label="Permalink to “Goal-based net-interest planning”">​</a></h1><p><strong>Status: Under development — not user selectable.</strong></p><p>Goal-based net-interest planning is not currently available to users. No Goal benchmark measurements, strategy comparisons or sensitivity graphs are published yet; work on the planner and its verification is ongoing. The browser marks the mode as disabled, and the public configuration validator and JSON schema reject <code>simulation.mode: &quot;goal&quot;</code>.</p><p>The existing goal-aware runtime, provenance ledger, strategy search code and direct runtime tests are retained as development material. They should not be interpreted as a supported public feature or as a reason to enable Goal mode.</p><h2 id="agreed-architecture" tabindex="-1">Agreed architecture <a class="header-anchor" href="#agreed-architecture" aria-label="Permalink to “Agreed architecture”">​</a></h2><ul><li><strong>Simulation runtime:</strong> remains strategy-independent and owns authoritative event processing, financial accounting, provenance, liquidity validation and finalisation.</li><li><strong>Greedy, GSS and Absolute R+:</strong> remain scoped date-range strategies. Their existing search objectives, ordering and performance characteristics must not be changed to serve Goal mode.</li><li><strong>Absolute R:</strong> is the intended first strategy to receive a dedicated earliest-achievement Goal objective.</li><li><strong>Public availability:</strong> Goal mode remains disabled until Absolute R&#39;s goal planner, accounting edge cases, adversarial tests and documentation are complete.</li></ul><p>The internal goal implementation is not yet accepted as production-ready. In particular, do not infer that existing Goal-mode tests establish strategy optimality or complete user-facing support.</p><p>See the <a href="./goal-mode-rework-plan.html">Goal-mode rework plan</a> for the implementation contract.</p>`,8)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};